&reftitle.description;
public mixedYaf_Request_Abstract::getEnv stringname mixeddefault
Obtém uma variável ENV.

  &reftitle.examples;

   Exemplo de Yaf_Request_Abstract::getEnv


<?php
class IndexController extends Yaf_Controller_Abstract
{
    public function indexAction()
    {
        // Supondo que o processo seja executado com APPLICATION_ENV=development
        $env = $this->getRequest()->getEnv("APPLICATION_ENV", "production");

        var_dump($env);
    }
}
?>

   &example.outputs.similar;


string(11) "development"
